<script setup lang="ts">
definePageMeta({ layout: "admin", middleware: "admin" });
useSeoMeta({ title: "Users | Portfolio admin", robots: "noindex, nofollow" });
interface Response { data: { items: Array<{ id: string; email: string; status: string; createdAt: string; roles: Array<{ role: { key: string; name: string } }>; oauthIdentities: unknown[]; _count: { sessions: number } }> } }
const { data, error, refresh } = await useLazyFetch<Response>("/api/admin/security/users", { query: { perPage: 50 } });
</script>
<template><div class="admin-page"><header class="admin-page-header"><div><p class="admin-eyebrow">Security</p><h1>Users</h1><p>Invite-only accounts, assigned roles, identities, and sessions.</p></div></header><AdminSkeleton v-if="!data && !error" :rows="5" /><div v-else-if="error && !data" class="admin-empty-state"><strong>Users could not be loaded.</strong><button @click="() => refresh()">Try again</button></div><section v-else class="admin-section"><div class="admin-data-table"><div class="admin-table-head"><span>Account</span><span>Roles</span><span>Sessions</span><span>Status</span></div><div v-for="user in data?.data.items" :key="user.id" class="admin-table-row"><div><strong>{{ user.email }}</strong><small>{{ new Date(user.createdAt).toLocaleDateString() }}</small></div><span>{{ user.roles.map(({ role }) => role.name).join(', ') || 'No role' }}</span><span>{{ user._count.sessions }}</span><span class="admin-state-label">{{ user.status }}</span></div><p v-if="!data?.data.items.length" class="admin-muted admin-table-empty">No administrators yet. Bootstrap the first Owner from the operator script.</p></div></section></div></template>
